function ms_close_admin_pointer(o){jQuery.post(window.ajaxurl,{pointer:o,action:"dismiss-wp-pointer"})}jQuery(window).load(function(){var o=jQuery.parseJSON(window.MS_Admin_Pointers);for(var i in o){var n=o[i];jQuery(n.target).pointer({content:n.options.content,position:n.options.position,pointerWidth:350,close:ms_close_admin_pointer(i)}).pointer("open")}});
